49          </Badge>{' '}
50          Notifications
51          <Typography variant="srOnly" component="span">
52            {unread === 0 ? 'No unread notifications' : `${unread} unread notifications`}
53          </Typography>
54        </Typography>
55        <List dense>
56          {notices.map((n) => (
57            <ListItem key={n.id} selected={!n.read}>
58              <ListItemIcon>
59                <MailIcon color={n.read ? 'disabled' : 'primary'} />
60              </ListItemIcon>
61              <ListItemText primary={n.text} secondary={n.read ? 'Read' : 'Unread'} />
62            </ListItem>
63          ))}
64        </List>
65        <Button
66          disabled={unread === 0}
67          onClick={() => setNotices(notices.map((n) => ({ ...n, read: true })))}
68        >
69          Mark all as read
70        </Button>
71      </Paper>
72    );
73  }

